class Solution {
public:
    std::vector<int> secondGreaterElement(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> ans(n, -1);
        std::vector<int> s1, s2, temp;
        for (int i = 0; i < n; ++i) {
            int x = nums[i];
            while (!s2.empty() && nums[s2.back()] < x) {
                ans[s2.back()] = x;
                s2.pop_back();
            }
            temp.clear();
            while (!s1.empty() && nums[s1.back()] < x) {
                temp.push_back(s1.back());
                s1.pop_back();
            }
            while (!temp.empty()) {
                s2.push_back(temp.back());
                temp.pop_back();
            }
            s1.push_back(i);
        }
        return ans;
    }
};

class Solution {
    public int[] secondGreaterElement(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        java.util.Arrays.fill(ans, -1);
        java.util.ArrayDeque<Integer> s1 = new java.util.ArrayDeque<>();
        java.util.ArrayDeque<Integer> s2 = new java.util.ArrayDeque<>();
        java.util.ArrayDeque<Integer> temp = new java.util.ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            while (!s2.isEmpty() && nums[s2.peek()] < x) {
                ans[s2.pop()] = x;
            }
            while (!s1.isEmpty() && nums[s1.peek()] < x) {
                temp.push(s1.pop());
            }
            while (!temp.isEmpty()) {
                s2.push(temp.pop());
            }
            s1.push(i);
        }
        return ans;
    }
}

